-- Correct outer-row qualification in every audience/ownership RLS expression.
-- Never compare unqualified vatra_id with an aliased table's own column.
drop policy if exists "profile_preferences_insert_owner" on public.vatra_profile_preferences;
create policy "profile_preferences_insert_owner" on public.vatra_profile_preferences for insert to authenticated with check (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_preferences.vatra_id and a.user_id=(select auth.uid())));
drop policy if exists "profile_preferences_update_owner" on public.vatra_profile_preferences;
create policy "profile_preferences_update_owner" on public.vatra_profile_preferences for update to authenticated using (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_preferences.vatra_id and a.user_id=(select auth.uid()))) with check (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_preferences.vatra_id and a.user_id=(select auth.uid())));
drop policy if exists "profile_details_audience_read" on public.vatra_profile_details;
create policy "profile_details_audience_read" on public.vatra_profile_details for select to authenticated using (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_details.vatra_id and a.user_id=(select auth.uid())) or ((visibility='public' or (visibility='friends' and exists(select 1 from public.vatra_friendships f join public.accounts viewer on viewer.vatra_id in (f.requester_id,f.recipient_id) where viewer.user_id=(select auth.uid()) and f.status='accepted' and ((f.requester_id=public.vatra_profile_details.vatra_id and f.recipient_id=viewer.vatra_id) or (f.recipient_id=public.vatra_profile_details.vatra_id and f.requester_id=viewer.vatra_id))))) and (coalesce((select pref.profile_visibility from public.vatra_profile_preferences pref where pref.vatra_id=public.vatra_profile_details.vatra_id),'public')='public' or exists(select 1 from public.vatra_friendships f join public.accounts viewer on viewer.vatra_id in (f.requester_id,f.recipient_id) where viewer.user_id=(select auth.uid()) and f.status='accepted' and ((f.requester_id=public.vatra_profile_details.vatra_id and f.recipient_id=viewer.vatra_id) or (f.recipient_id=public.vatra_profile_details.vatra_id and f.requester_id=viewer.vatra_id))))));
drop policy if exists "profile_details_insert_owner" on public.vatra_profile_details;
create policy "profile_details_insert_owner" on public.vatra_profile_details for insert to authenticated with check (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_details.vatra_id and a.user_id=(select auth.uid())));
drop policy if exists "profile_details_update_owner" on public.vatra_profile_details;
create policy "profile_details_update_owner" on public.vatra_profile_details for update to authenticated using (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_details.vatra_id and a.user_id=(select auth.uid()))) with check (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_details.vatra_id and a.user_id=(select auth.uid())));
drop policy if exists "profile_details_delete_owner" on public.vatra_profile_details;
create policy "profile_details_delete_owner" on public.vatra_profile_details for delete to authenticated using (exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_details.vatra_id and a.user_id=(select auth.uid())));
drop policy if exists "closed_profile_posts_gate" on public.feed_posts;
create policy "closed_profile_posts_gate" on public.feed_posts as restrictive for select to authenticated using ((exists(select 1 from public.accounts a where a.vatra_id=public.feed_posts.author_vatra_id and a.user_id=(select auth.uid())) or coalesce((select pref.profile_visibility from public.vatra_profile_preferences pref where pref.vatra_id=public.feed_posts.author_vatra_id),'public')='public' or exists(select 1 from public.vatra_friendships f join public.accounts viewer on viewer.vatra_id in (f.requester_id,f.recipient_id) where viewer.user_id=(select auth.uid()) and f.status='accepted' and ((f.requester_id=public.feed_posts.author_vatra_id and f.recipient_id=viewer.vatra_id) or (f.recipient_id=public.feed_posts.author_vatra_id and f.requester_id=viewer.vatra_id)))));
drop policy if exists "closed_profile_media_gate" on public.vatra_profile_media;
create policy "closed_profile_media_gate" on public.vatra_profile_media as restrictive for select to authenticated using ((exists(select 1 from public.accounts a where a.vatra_id=public.vatra_profile_media.vatra_id and a.user_id=(select auth.uid())) or coalesce((select pref.profile_visibility from public.vatra_profile_preferences pref where pref.vatra_id=public.vatra_profile_media.vatra_id),'public')='public' or exists(select 1 from public.vatra_friendships f join public.accounts viewer on viewer.vatra_id in (f.requester_id,f.recipient_id) where viewer.user_id=(select auth.uid()) and f.status='accepted' and ((f.requester_id=public.vatra_profile_media.vatra_id and f.recipient_id=viewer.vatra_id) or (f.recipient_id=public.vatra_profile_media.vatra_id and f.requester_id=viewer.vatra_id)))));
drop policy if exists "closed_profile_presence_gate" on public.profile_presence;
create policy "closed_profile_presence_gate" on public.profile_presence as restrictive for select to authenticated using ((exists(select 1 from public.accounts a where a.vatra_id=public.profile_presence.vatra_id and a.user_id=(select auth.uid())) or coalesce((select pref.profile_visibility from public.vatra_profile_preferences pref where pref.vatra_id=public.profile_presence.vatra_id),'public')='public' or exists(select 1 from public.vatra_friendships f join public.accounts viewer on viewer.vatra_id in (f.requester_id,f.recipient_id) where viewer.user_id=(select auth.uid()) and f.status='accepted' and ((f.requester_id=public.profile_presence.vatra_id and f.recipient_id=viewer.vatra_id) or (f.recipient_id=public.profile_presence.vatra_id and f.requester_id=viewer.vatra_id)))));
